<script setup>
import {ref} from 'vue'
import {ElMessage} from 'element-plus'
import request from '@/utils/request'
const open=ref(false),rows=ref([]),busy=ref(false),saving=ref(false),hasMore=ref(false),form=ref({id:null,code:'',category:'',part:'',symptom:''})
async function load(more=false){if(busy.value)return;busy.value=true;try{const params={all:true};if(more && rows.value.length)params.afterId=rows.value[rows.value.length-1].id;const data=(await request({url:'/equipment/fault-codes',method:'get',params})).data||[];rows.value=more?[...rows.value,...data]:data;hasMore.value=data.length===200}finally{busy.value=false}}
async function show(){open.value=true;await load()}
function reset(){form.value={id:null,code:'',category:'',part:'',symptom:''}}
function edit(row){form.value={id:row.id,code:row.code,category:row.category,part:row.part,symptom:row.symptom}}
async function save(){const f=form.value;if(!/^[A-Za-z0-9_-]{1,64}$/.test(f.code)||![f.category,f.part,f.symptom].every(x=>x.trim()))return ElMessage.warning('请填写代码、类别、部位和现象');saving.value=true;try{await request({url:'/equipment/fault-codes'+(f.id?'/'+f.id:''),method:f.id?'put':'post',data:{code:f.code,category:f.category,part:f.part,symptom:f.symptom}});reset();await load();ElMessage.success('故障代码已保存')}finally{saving.value=false}}
async function toggle(row){if(busy.value)return;busy.value=true;try{await request({url:'/equipment/fault-codes/'+row.id+'/status',method:'put',data:{status:row.status==='ACTIVE'?'INACTIVE':'ACTIVE'}});row.status=row.status==='ACTIVE'?'INACTIVE':'ACTIVE'}finally{busy.value=false}}
</script>
<template><span><el-button @click="show">故障代码管理</el-button><el-dialog v-model="open" title="故障代码管理" width="min(95%, 850px)"><p>按类别、部位和现象维护代码，停用后不能用于新维修记录。</p><el-form label-position="top"><el-row :gutter="12"><el-col :span="12"><el-form-item label="代码"><el-input v-model="form.code" maxlength="64" placeholder="字母、数字、下划线或连字符"/></el-form-item></el-col><el-col :span="12"><el-form-item label="类别"><el-input v-model="form.category" maxlength="80"/></el-form-item></el-col><el-col :span="12"><el-form-item label="部位"><el-input v-model="form.part" maxlength="80"/></el-form-item></el-col><el-col :span="12"><el-form-item label="现象"><el-input v-model="form.symptom" maxlength="80"/></el-form-item></el-col></el-row><el-button type="primary" :loading="saving" @click="save">{{form.id?'保存修改':'新增代码'}}</el-button><el-button v-if="form.id" @click="reset">取消编辑</el-button></el-form><el-table v-loading="busy" :data="rows"><el-table-column prop="code" label="代码"/><el-table-column prop="category" label="类别"/><el-table-column prop="part" label="部位"/><el-table-column prop="symptom" label="现象"/><el-table-column label="状态"><template #default="{row}">{{row.status==='ACTIVE'?'启用':'停用'}}</template></el-table-column><el-table-column label="操作" width="125"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link :disabled="busy" @click="toggle(row)">{{row.status==='ACTIVE'?'停用':'启用'}}</el-button></template></el-table-column></el-table><el-button v-if="hasMore" :loading="busy" @click="load(true)">加载更多</el-button></el-dialog></span></template>
